    public Object parseWsTrade(Object trade, Object... optionalArgs)
    {
        //
        //     {
        //         "d": "order:59091012956:a:BTC",
        //         "c": "user:up105393824:a:BTC",
        //         "a": "0.00096420",
        //         "ds": 0,
        //         "cs": "0.00096420",
        //         "user": "up105393824",
        //         "symbol": "BTC",
        //         "symbol2": "USD",
        //         "amount": "0.00096420",
        //         "buy": 59091012956,
        //         "order": 59091012956,
        //         "sell": 59090796005,
        //         "price": 19135,
        //         "type": "buy",
        //         "time": "2022-09-24T19:36:18.466Z",
        //         "balance": "0.00096420",
        //         "fee_amount": "0.05",
        //         "id": "59091012962"
        //     }
        // Note symbol and symbol2 are inverse on sell and amount is in symbol currency.
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object side = this.safeString(trade, "type");
        Object price = this.safeString(trade, "price");
        Object datetime = this.safeString(trade, "time");
        Object baseId = this.safeString(trade, "symbol");
        Object quoteId = this.safeString(trade, "symbol2");
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        Object amount = this.safeString(trade, "amount");
        if (Helpers.isTrue(Helpers.isEqual(side, "sell")))
        {
            symbol = Helpers.add(Helpers.add(quote, "/"), base);
            amount = Precise.stringDiv(amount, price); // due to rounding errors amount in not exact to trade
        }
        final Object finalSymbol = symbol;
        final Object finalSide = side;
        final Object finalAmount = amount;
        Object parsedTrade = new java.util.HashMap<String, Object>() {{
            put( "id", Cex.this.safeString(trade, "id") );
            put( "order", Cex.this.safeString(trade, "order") );
            put( "info", trade );
            put( "timestamp", Cex.this.parse8601(datetime) );
            put( "datetime", datetime );
            put( "symbol", finalSymbol );
            put( "type", null );
            put( "side", finalSide );
            put( "takerOrMaker", null );
            put( "price", price );
            put( "cost", null );
            put( "amount", finalAmount );
            put( "fee", null );
        }};
        Object fee = this.safeString(trade, "fee_amount");
        if (Helpers.isTrue(!Helpers.isEqual(fee, null)))
        {
            final Object finalFee = fee;
            final Object finalQuote = quote;
            Helpers.addElementToObject(parsedTrade, "fee", new java.util.HashMap<String, Object>() {{
    put( "cost", finalFee );
    put( "currency", finalQuote );
    put( "rate", null );
}});
        }
        return this.safeTrade(parsedTrade, market);
    }

    public void handleOrderUpdate(Client client, Object message)
    {
        //
        //  partialExecution
        //     {
        //         "e": "order",
        //         "data": {
        //             "id": "150714937",
        //             "remains": "1000000",
        //             "price": "17513",
        //             "amount": 2000000, As Precision
        //             "time": "1654506118448",
        //             "type": "buy",
        //             "pair": {
        //                 "symbol1": "BTC",
        //                 "symbol2": "USD"
        //             },
        //             "fee": "0.15"
        //         }
        //     }
        //  canceled order
        //     {
        //         "e": "order",
        //         "data": {
        //             "id": "6310857",
        //             "remains": "200000000"
        //             "fremains": "2.00000000"
        //             "cancel": true,
        //             "pair": {
        //                 "symbol1": "BTC",
        //                 "symbol2": "USD"
        //             }
        //         }
        //     }
        //  fulfilledOrder
        //     {
        //         "e": "order",
        //         "data": {
        //             "id": "59098421630",
        //             "remains": "0",
        //             "pair": {
        //                 "symbol1": "BTC",
        //                 "symbol2": "USD"
        //             }
        //         }
        //     }
        //     {
        //         "e": "tx",
        //         "data": {
        //             "d": "order:59425993014:a:BTC",
        //             "c": "user:up105393824:a:BTC",
        //             "a": "0.00098152",
        //             "ds": 0,
        //             "cs": "0.00098152",
        //             "user": "up105393824",
        //             "symbol": "BTC",
        //             "symbol2": "USD",
        //             "amount": "0.00098152",
        //             "buy": 59425993014,
        //             "order": 59425993014,
        //             "sell": 59425986168,
        //             "price": 19306.6,
        //             "type": "buy",
        //             "time": "2022-10-02T01:11:15.148Z",
        //             "balance": "0.00098152",
        //             "fee_amount": "0.05",
        //             "id": "59425993020"
        //         }
        //     }
        //
        Object data = this.safeValue(message, "data", new java.util.HashMap<String, Object>() {{}});
        Object isTransaction = Helpers.isEqual(this.safeString(message, "e"), "tx");
        Object orderId = this.safeString2(data, "id", "order");
        Object remains = this.safeString(data, "remains");
        Object baseId = this.safeString(data, "symbol");
        Object quoteId = this.safeString(data, "symbol2");
        Object pair = this.safeValue(data, "pair");
        if (Helpers.isTrue(!Helpers.isEqual(pair, null)))
        {
            baseId = this.safeString(pair, "symbol1");
            quoteId = this.safeString(pair, "symbol2");
        }
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        Object market = this.safeMarket(symbol);
        remains = this.currencyFromPrecision(base, remains);
        if (Helpers.isTrue(Helpers.isEqual(this.orders, null)))
        {
            Object limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        Object storedOrders = this.orders;
        Object ordersBySymbol = this.safeValue(((io.github.ccxt.ws.ArrayCache)storedOrders).hashmap, symbol, new java.util.HashMap<String, Object>() {{}});
        Object order = this.safeValue(ordersBySymbol, orderId);
        if (Helpers.isTrue(Helpers.isEqual(order, null)))
        {
            order = this.parseWsOrderUpdate(data, market);
        }
        Helpers.addElementToObject(order, "remaining", remains);
        Object canceled = this.safeBool(data, "cancel", false);
        if (Helpers.isTrue(Helpers.isEqual(canceled, true)))
        {
            Helpers.addElementToObject(order, "status", "canceled");
        }
        if (Helpers.isTrue(isTransaction))
        {
            Helpers.addElementToObject(order, "status", "closed");
        }
        Object fee = this.safeNumber(data, "fee");
        if (Helpers.isTrue(!Helpers.isEqual(fee, null)))
        {
            final Object finalFee = fee;
            Helpers.addElementToObject(order, "fee", new java.util.HashMap<String, Object>() {{
    put( "cost", finalFee );
    put( "currency", quote );
    put( "rate", null );
}});
        }
        Object timestamp = this.safeInteger(data, "time");
        Helpers.addElementToObject(order, "timestamp", timestamp);
        Helpers.addElementToObject(order, "datetime", this.iso8601(timestamp));
        order = this.safeOrder(order);
        Helpers.callDynamically(storedOrders, "append", new Object[]{order});
        Object messageHash = Helpers.add("orders:", symbol);
        client.resolve(storedOrders, messageHash);
    }

    public Object parseWsOrderUpdate(Object order, Object... optionalArgs)
    {
        //
        //      {
        //          "id": "150714937",
        //          "remains": "1000000",
        //          "price": "17513",
        //          "amount": 2000000, As Precision
        //          "time": "1654506118448",
        //          "type": "buy",
        //          "pair": {
        //              "symbol1": "BTC",
        //              "symbol2": "USD"
        //          },
        //          "fee": "0.15"
        //      }
        //  transaction
        //      {
        //           "d": "order:59425993014:a:BTC",
        //           "c": "user:up105393824:a:BTC",
        //           "a": "0.00098152",
        //           "ds": 0,
        //           "cs": "0.00098152",
        //           "user": "up105393824",
        //           "symbol": "BTC",
        //           "symbol2": "USD",
        //           "amount": "0.00098152",
        //           "buy": 59425993014,
        //           "order": 59425993014,
        //           "sell": 59425986168,
        //           "price": 19306.6,
        //           "type": "buy",
        //           "time": "2022-10-02T01:11:15.148Z",
        //           "balance": "0.00098152",
        //           "fee_amount": "0.05",
        //           "id": "59425993020"
        //       }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object isTransaction = !Helpers.isEqual(this.safeValue(order, "d"), null);
        Object remainsPrecision = this.safeString(order, "remains");
        Object remaining = null;
        if (Helpers.isTrue(!Helpers.isEqual(remainsPrecision, null)))
        {
            if (Helpers.isTrue(Helpers.isEqual(market, null)))
            {
                return null;
            }
            remaining = this.currencyFromPrecision(Helpers.GetValue(market, "base"), remainsPrecision);
        }
        Object amount = this.safeString(order, "amount");
        if (!Helpers.isTrue(isTransaction))
        {
            if (Helpers.isTrue(Helpers.isEqual(market, null)))
            {
                return null;
            }
            this.currencyFromPrecision(Helpers.GetValue(market, "base"), amount);
        }
        Object baseId = this.safeString(order, "symbol");
        Object quoteId = this.safeString(order, "symbol2");
        Object pair = this.safeValue(order, "pair");
        if (Helpers.isTrue(!Helpers.isEqual(pair, null)))
        {
            baseId = this.safeString(order, "symbol1");
            quoteId = this.safeString(order, "symbol2");
        }
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = null;
        if (Helpers.isTrue(Helpers.isTrue(!Helpers.isEqual(base, null)) && Helpers.isTrue(!Helpers.isEqual(quote, null))))
        {
            symbol = Helpers.add(Helpers.add(base, "/"), quote);
        }
        market = this.safeMarket(symbol, market);
        Object time = this.safeInteger(order, "time", this.milliseconds());
        Object timestamp = time;
        if (Helpers.isTrue(isTransaction))
        {
            timestamp = this.parse8601(time);
        }
        Object canceled = this.safeBool(order, "cancel", false);
        Object status = "open";
        if (Helpers.isTrue(Helpers.isEqual(canceled, true)))
        {
            status = "canceled";
        } else if (Helpers.isTrue(isTransaction))
        {
            status = "closed";
        }
        final Object finalTimestamp = timestamp;
        final Object finalStatus = status;
        final Object finalSymbol = symbol;
        final Object finalRemaining = remaining;
        final Object finalQuote = quote;
        Object parsedOrder = new java.util.HashMap<String, Object>() {{
            put( "id", Cex.this.safeString2(order, "id", "order") );
            put( "clientOrderId", null );
            put( "info", order );
            put( "timestamp", finalTimestamp );
            put( "datetime", Cex.this.iso8601(finalTimestamp) );
            put( "lastTradeTimestamp", null );
            put( "status", finalStatus );
            put( "symbol", finalSymbol );
            put( "type", null );
            put( "timeInForce", null );
            put( "postOnly", null );
            put( "side", Cex.this.safeString(order, "type") );
            put( "price", Cex.this.safeNumber(order, "price") );
            put( "stopPrice", null );
            put( "triggerPrice", null );
            put( "average", null );
            put( "cost", null );
            put( "amount", amount );
            put( "filled", null );
            put( "remaining", finalRemaining );
            put( "fee", new java.util.HashMap<String, Object>() {{
                put( "cost", Cex.this.safeNumber2(order, "fee", "fee_amount") );
                put( "currency", finalQuote );
                put( "rate", null );
            }} );
            put( "trades", null );
        }};
        if (Helpers.isTrue(isTransaction))
        {
            Helpers.addElementToObject(parsedOrder, "trades", this.parseWsTrade(order, market));
        }
        return this.safeOrder(parsedOrder, market);
    }

    public Object fromPrecision(Object amount, Object scale)
    {
        if (Helpers.isTrue(Helpers.isEqual(amount, null)))
        {
            return null;
        }
        var precise = new Precise(amount);
        precise.decimals = this.sum(precise.decimals, scale);
        precise.reduce();
        return String.valueOf(precise);
    }

    public Object currencyFromPrecision(Object currency, Object amount)
    {
        Object scale = this.safeInteger(Helpers.GetValue(this.currencies, currency), "precision", 0);
        return this.fromPrecision(amount, scale);
    }

    public void handleOrdersSnapshot(Client client, Object message)
    {
        //
        //     {
        //         "e": "open-orders",
        //         "data": [{
        //             "id": "59098421631",
        //             "time": "1664062285425",
        //             "type": "buy",
        //             "price": "18920",
        //             "amount": "0.00100000",
        //             "pending": "0.00100000"
        //         }],
        //         "oid": 1,
        //         "ok": "ok"
        //     }
        //
        Object symbol = this.safeString(message, "oid"); // symbol is set as requestId in watchOrders
        Object rawOrders = this.safeValue(message, "data", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object myOrders = this.orders;
        if (Helpers.isTrue(Helpers.isEqual(myOrders, null)))
        {
            Object limit = this.safeInteger(this.options, "ordersLimit", 1000);
            myOrders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(rawOrders)); i++)
        {
            Object rawOrder = Helpers.GetValue(rawOrders, i);
            Object market = this.safeMarket(symbol);
            Object order = this.parseOrder(rawOrder, market);
            Helpers.addElementToObject(order, "status", "open");
            Helpers.callDynamically(myOrders, "append", new Object[]{order});
        }
        this.orders = myOrders;
        Object messageHash = Helpers.add("orders:", symbol);
        Object ordersLength = Helpers.getArrayLength(myOrders);
        if (Helpers.isTrue(Helpers.isGreaterThan(ordersLength, 0)))
        {
            client.resolve(myOrders, messageHash);
        }
    }

    /**
     * @method
     * @name cex#watchOrderBook
     * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @see https://trade.cex.io/docs/#websocket-public-api-calls-order-book-subscribe
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.ws.WsOrderBook> watchOrderBook(Object symbol2, Object... optionalArgs)
    {
        final Object symbol3 = symbol2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object symbol = symbol3;
            Object limit = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            (this.authenticate()).join();
            Object market = this.market(symbol);
            symbol = Helpers.GetValue(market, "symbol");
            Object url = Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "ws");
            Object messageHash = Helpers.add("orderbook:", symbol);
            Object depth = ((Helpers.isTrue((Helpers.isEqual(limit, null))))) ? 0 : limit;
            Object subscribe = new java.util.HashMap<String, Object>() {{
                put( "e", "order-book-subscribe" );
                put( "data", new java.util.HashMap<String, Object>() {{
                    put( "pair", new java.util.ArrayList<Object>(java.util.Arrays.asList(Helpers.GetValue(market, "baseId"), Helpers.GetValue(market, "quoteId"))) );
                    put( "subscribe", true );
                    put( "depth", depth );
                }} );
                put( "oid", Cex.this.requestId() );
            }};
            Object request = this.deepExtend(subscribe, parameters);
            Object orderbook = (this.watch(url, messageHash, request, messageHash, null)).join();
            return Helpers.callDynamically(orderbook, "limit", new Object[]{});
        }).thenApply(io.github.ccxt.TypedCores::toOrderBookSnapshot);

    }

    public void handleOrderBookSnapshot(Client client, Object message)
    {
        //
        //     {
        //         "e": "order-book-subscribe",
        //         "data": {
        //             "timestamp": 1663762032,
        //             "timestamp_ms": 1663762031680,
        //             "bids": [
        //                 [ 241.947, 155.91626 ],
        //                 [ 241, 154 ],
        //             ],
        //             "asks": [
        //                 [ 242.947, 155.91626 ],
        //                 [ 243, 154 ],    ],
        //             "pair": "BTC:USDT",
        //             "id": 616267120,
        //             "sell_total": "13.59066946",
        //             "buy_total": "163553.625948"
        //         },
        //         "oid": "1",
        //         "ok": "ok"
        //     }
        //
        Object data = this.safeValue(message, "data", new java.util.HashMap<String, Object>() {{}});
        Object pair = this.safeString(data, "pair");
        Object symbol = this.pairToSymbol(pair);
        Object messageHash = Helpers.add("orderbook:", symbol);
        Object timestamp = this.safeInteger2(data, "timestamp_ms", "timestamp");
        Object incrementalId = this.safeInteger(data, "id");
        Object orderbook = this.orderBook(new java.util.HashMap<String, Object>() {{}});
        Object snapshot = this.parseOrderBook(data, symbol, timestamp, "bids", "asks");
        Helpers.addElementToObject(snapshot, "nonce", incrementalId);
        Helpers.callDynamically(orderbook, "reset", new Object[]{snapshot});
        Helpers.addElementToObject(Helpers.GetValue(this.options, "orderbook"), symbol, new java.util.HashMap<String, Object>() {{
    put( "incrementalId", incrementalId );
}});
        Helpers.addElementToObject(this.orderbooks, symbol, orderbook);
        client.resolve(orderbook, messageHash);
    }

    public Object pairToSymbol(Object pair)
    {
        Object parts = Helpers.split(pair, ":");
        Object baseId = this.safeString(parts, 0);
        Object quoteId = this.safeString(parts, 1);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        return symbol;
    }

    public void handleOrderBookUpdate(Client client, Object message)
    {
        //
        //     {
        //         "e": "md_update",
        //         "data": {
        //             "id": 616267121,
        //             "pair": "BTC:USDT",
        //             "time": 1663762031719,
        //             "bids": [],
        //             "asks": [
        //                 [122, 23]
        //             ]
        //         }
        //     }
        //
        Object data = this.safeValue(message, "data", new java.util.HashMap<String, Object>() {{}});
        Object incrementalId = this.safeInteger(data, "id");
        Object pair = this.safeString(data, "pair", "");
        Object symbol = this.pairToSymbol(pair);
        Object storedOrderBook = this.safeValue(this.orderbooks, symbol);
        Object messageHash = Helpers.add("orderbook:", symbol);
        if (Helpers.isTrue(!Helpers.isEqual(incrementalId, Helpers.add(Helpers.GetValue(storedOrderBook, "nonce"), 1))))
        {
            ((java.util.Map<String,Object>)client.subscriptions).remove((String)messageHash);
            client.reject(Helpers.add(this.id, " watchOrderBook() skipped a message"), messageHash);
            return;
        }
        Object timestamp = this.safeInteger(data, "time");
        Object asks = this.safeValue(data, "asks", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object bids = this.safeValue(data, "bids", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        this.handleDeltas(Helpers.GetValue(storedOrderBook, "asks"), asks);
        this.handleDeltas(Helpers.GetValue(storedOrderBook, "bids"), bids);
        Helpers.addElementToObject(storedOrderBook, "timestamp", timestamp);
        Helpers.addElementToObject(storedOrderBook, "datetime", this.iso8601(timestamp));
        Helpers.addElementToObject(storedOrderBook, "nonce", incrementalId);
        client.resolve(storedOrderBook, messageHash);
    }

    public void handleDelta(Object bookside, Object delta)
    {
        Object bidAsk = this.parseOrderBookBidAsk(delta, 0, 1);
        Helpers.callDynamically(bookside, "storeArray", new Object[]{bidAsk});
    }

    public void handleDeltas(Object bookside, Object deltas)
    {
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(deltas)); i++)
        {
            this.handleDelta(bookside, Helpers.GetValue(deltas, i));
        }
    }

    /**
     * @method
     * @name cex#watchOHLCV
     * @see https://cex.io/websocket-api#minute-data
     * @description watches historical candlestick data containing the open, high, low, and close price, and the volume of a market. It will return the last 120 minutes with the selected timeframe and then 1m candle updates after that.
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
     * @param {string} timeframe the length of time each candle represents.
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum amount of candles to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
     */
    public java.util.concurrent.CompletableFuture<java.util.List<io.github.ccxt.types.OHLCV>> watchOHLCV(Object symbol2, Object... optionalArgs)
    {
        final Object symbol3 = symbol2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object symbol = symbol3;
            Object timeframe = Helpers.getArg(optionalArgs, 0, "1m");
            Object since = Helpers.getArg(optionalArgs, 1, null);
            Object limit = Helpers.getArg(optionalArgs, 2, null);
            Object parameters = Helpers.getArg(optionalArgs, 3, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            symbol = Helpers.GetValue(market, "symbol");
            Object messageHash = Helpers.add("ohlcv:", symbol);
            Object url = Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "ws");
            Object request = new java.util.HashMap<String, Object>() {{
                put( "e", "init-ohlcv" );
                put( "i", timeframe );
                put( "rooms", new java.util.ArrayList<Object>(java.util.Arrays.asList(Helpers.add(Helpers.add(Helpers.add("pair-", Helpers.GetValue(market, "baseId")), "-"), Helpers.GetValue(market, "quoteId")))) );
            }};
            Object ohlcv = (this.watch(url, messageHash, this.extend(request, parameters), messageHash, null)).join();
            if (Helpers.isTrue(this.newUpdates))
            {
                limit = Helpers.callDynamically(ohlcv, "getLimit", new Object[]{symbol, limit});
            }
            return this.filterBySinceLimit(ohlcv, since, limit, 0, true);
        }).thenApply(io.github.ccxt.TypedCores::toOHLCVList);

    }

    public void handleInitOHLCV(Client client, Object message)
    {
        //
        //     {
        //         "e": "init-ohlcv-data",
        //         "data": [
        //             [
        //                 1663660680,
        //                 "19396.4",
        //                 "19396.4",
        //                 "19396.4",
        //                 "19396.4",
        //                 "1262861"
        //             ],
        //             ...
        //         ],
        //         "pair": "BTC:USDT"
        //     }
        //
        Object pair = this.safeString(message, "pair");
        if (Helpers.isTrue(Helpers.isEqual(pair, null)))
        {
            return;
        }
        Object parts = Helpers.split(pair, ":");
        Object baseId = this.safeString(parts, 0);
        Object quoteId = this.safeString(parts, 1);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        Object market = this.safeMarket(symbol);
        Object messageHash = Helpers.add("ohlcv:", symbol);
        Object data = this.safeValue(message, "data", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object limit = this.safeInteger(this.options, "OHLCVLimit", 1000);
        var stored = new ArrayCache.ArrayCacheByTimestamp(((Number)limit).intValue());
        Object sorted = this.sortBy(data, 0);
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(sorted)); i++)
        {
            Helpers.callDynamically(stored, "append", new Object[]{this.parseOHLCV(Helpers.GetValue(sorted, i), market)});
        }
        if (!Helpers.isTrue((Helpers.inOp(this.ohlcvs, symbol))))
        {
            Helpers.addElementToObject(this.ohlcvs, symbol, new java.util.HashMap<String, Object>() {{}});
        }
        Helpers.addElementToObject(Helpers.GetValue(this.ohlcvs, symbol), "unknown", stored);
        client.resolve(stored, messageHash);
    }

